//! Walkers for the fuzz targets: each function reads **every** accessor of a root and descends
//! into tables, lists and unions, recording the result (value or error) as text.
//!
//! Each walker exists in two versions generated by the same macro: over the checked reader
//! (`X`) and over the verified view (`XVerified`). Since the accessors have the same names,
//! both versions produce the same text when they read the same value: that is what the
//! `differential` target compares. Over unverified bytes (`read` target), a walk must never
//! panic; `depth` bounds the descent through cycles (`Leaf.next`).

use std::fmt::Debug;

/// Maximum descent depth (above verify's `max_depth` of 64).
pub const DEPTH: u32 = 70;

/// Elements walked per list. Without `verify`, a `[Table]` with `elem_fixed_len = 0`
/// can announce ~2³² elements in a few bytes (lazy reads are O(1) per access, spec §7.1;
/// `verify` stops it through the budget). Walking all of them would only measure the
/// walker. The limit is the same for both versions, so the differential is unaffected.
pub const MAX_ELEMS: usize = 4096;

pub type Out = Vec<String>;

fn push<T: Debug>(out: &mut Out, k: &str, v: T) {
    out.push(format!("{k}={v:?}"));
}

/// `Result<Option<T>>` of a table/union: records its shape and returns the child, if any.
fn opt<T, E: Debug>(out: &mut Out, k: &str, r: Result<Option<T>, E>) -> Option<T> {
    match r {
        Ok(Some(t)) => {
            out.push(format!("{k}=Some"));
            Some(t)
        }
        Ok(None) => {
            out.push(format!("{k}=None"));
            None
        }
        Err(e) => {
            out.push(format!("{k}=Err({e:?})"));
            None
        }
    }
}

fn req<T, E: Debug>(out: &mut Out, k: &str, r: Result<T, E>) -> Option<T> {
    match r {
        Ok(t) => {
            out.push(format!("{k}=Ok"));
            Some(t)
        }
        Err(e) => {
            out.push(format!("{k}=Err({e:?})"));
            None
        }
    }
}

/// `[string]` (`StrList` or `VStrList`): `len`, then `get` (validates UTF-8).
macro_rules! strs {
    ($out:expr, $k:expr, $l:expr) => {{
        let l = $l;
        $out.push(format!("{}.len={}", $k, l.len()));
        for i in 0..l.len().min(MAX_ELEMS) {
            $out.push(format!("{}[{i}]={:?}", $k, l.get(i)));
        }
        let _ = l.get(l.len());
    }};
}

/// `[bytes]` (`StrList`): `len`, then `get_bytes` (bytes need not be UTF-8).
macro_rules! blobs {
    ($out:expr, $k:expr, $l:expr) => {{
        let l = $l;
        $out.push(format!("{}.len={}", $k, l.len()));
        for i in 0..l.len().min(MAX_ELEMS) {
            $out.push(format!("{}[{i}]={:?}", $k, l.get_bytes(i)));
        }
        let _ = l.get_bytes(l.len());
    }};
}

/// Error lines of a walk: `field=Err(..)`. The value always comes after the first `=` and
/// only starts with `Err(` when the accessor failed (user data appears inside
/// `Ok(..)`/`Some(..)`, escaped by `Debug`).
pub fn errors(out: &Out) -> Vec<&String> {
    out.iter().filter(|l| l.split_once('=').is_some_and(|(_, v)| v.starts_with("Err("))).collect()
}

/// Table list (`ListR`/`VListR`): `len`, an out-of-range `get`, each element.
macro_rules! tables {
    ($out:expr, $k:expr, $l:expr, $f:expr, $d:expr) => {{
        let l = $l;
        $out.push(format!("{}.len={}", $k, l.len()));
        $out.push(format!("{}.oob={}", $k, l.get(l.len()).is_err()));
        for (i, e) in l.iter().take(MAX_ELEMS).enumerate() {
            if let Some(e) = req($out, &format!("{}[{i}]", $k), e) {
                $f(e, $d, $out);
            }
        }
    }};
}

macro_rules! scalars {
    ($out:expr, $k:expr, $l:expr) => {{
        let l = $l;
        $out.push(format!("{}.len={}", $k, l.len()));
        $out.push(format!("{}={:?}", $k, l.iter().take(MAX_ELEMS).collect::<Vec<_>>()));
    }};
}

/// Walk functions for a set of types (checked or verified).
macro_rules! walkers {
    (
        mod $m:ident;
        conformance: $Root:ty, $Leaf:ty, $Choice:ident, $Extra:ty, $Holder:ty;
        edge: $Edge:ty, $Small:ty, $Big:ty, $Pick:ident;
        bank: $Tx:ty, $Entry:ty;
        game: $Frame:ty, $Entity:ty;
        iot: $Tel:ty;
        stream: $Chunk:ty;
    ) => {
        pub mod $m {
            use super::*;
            use graven_codegen_tests::edge as e;
            use graven_conformance::generated as g;

            pub fn leaf(l: $Leaf, d: u32, out: &mut Out) {
                push(out, "n", l.n());
                push(out, "s", l.s());
                if let Some(n) = opt(out, "next", l.next()) {
                    if d > 0 {
                        leaf(n, d - 1, out);
                    }
                }
            }

            fn choice(c: g::$Choice<'_>, d: u32, out: &mut Out) {
                match c {
                    g::$Choice::Leaf(l) => {
                        out.push("Leaf".into());
                        leaf(l, d, out)
                    }
                    g::$Choice::Unknown(t) => push(out, "Unknown", t),
                }
            }

            pub fn root(r: &$Root, out: &mut Out) {
                let d = DEPTH;
                push(out, "a_u8", r.a_u8());
                push(out, "a_i16", r.a_i16());
                push(out, "a_u32", r.a_u32());
                push(out, "a_i64", r.a_i64());
                push(out, "a_u128", r.a_u128());
                push(out, "a_i128", r.a_i128());
                push(out, "a_f32", r.a_f32().map(f32::to_bits));
                push(out, "a_f64", r.a_f64().map(f64::to_bits));
                push(out, "flag", r.flag());
                push(out, "flag2", r.flag2());
                push(out, "color", r.color());
                push(out, "point", r.point());
                push(out, "name", r.name());
                push(out, "blob", r.blob());
                if let Some(l) = opt(out, "nums", r.nums()) {
                    scalars!(out, "nums", l);
                }
                if let Some(l) = opt(out, "points", r.points()) {
                    scalars!(out, "points", l);
                }
                if let Some(l) = opt(out, "leaves", r.leaves()) {
                    tables!(out, "leaves", l, leaf, d);
                }
                if let Some(l) = opt(out, "names", r.names()) {
                    strs!(out, "names", l);
                }
                if let Some(l) = opt(out, "blobs", r.blobs()) {
                    blobs!(out, "blobs", l);
                }
                if let Some(c) = opt(out, "child", r.child()) {
                    leaf(c, d, out);
                }
                if let Some(c) = opt(out, "choice", r.choice()) {
                    choice(c, d, out);
                }
            }

            pub fn extra(r: &$Extra, out: &mut Out) {
                let d = DEPTH;
                push(out, "flags", r.flags());
                if let Some(l) = opt(out, "bools", r.bools()) {
                    scalars!(out, "bools", l);
                }
                if let Some(l) = opt(out, "colors", r.colors()) {
                    scalars!(out, "colors", l);
                }
                if let Some(l) = opt(out, "names", r.names()) {
                    strs!(out, "names", l);
                }
                if let Some(l) = opt(out, "blobs", r.blobs()) {
                    blobs!(out, "blobs", l);
                }
                if let Some(c) = req(out, "pick", r.pick()) {
                    choice(c, d, out);
                }
                if let Some(l) = opt(out, "leaves", r.leaves()) {
                    tables!(out, "leaves", l, leaf, d);
                }
                push(out, "e", r.e());
                push(out, "tail", r.tail());
            }

            pub fn holder(r: &$Holder, out: &mut Out) {
                if let Some(l) = req(out, "items", r.items()) {
                    tables!(out, "items", l, leaf, DEPTH);
                }
            }

            fn small(s: $Small, _d: u32, out: &mut Out) {
                push(out, "v", s.v());
                push(out, "ok", s.ok());
            }

            fn big(b: $Big, _d: u32, out: &mut Out) {
                push(out, "s", b.s());
                push(out, "b", b.b());
            }

            fn pick(p: e::$Pick<'_>, out: &mut Out) {
                match p {
                    e::$Pick::Small(s) => small(s, 0, out),
                    e::$Pick::Big(b) => big(b, 0, out),
                    e::$Pick::Unknown(t) => push(out, "Unknown", t),
                }
            }

            pub fn edge(r: &$Edge, out: &mut Out) {
                push(out, "type", r.r#type());
                push(out, "req_str", r.req_str());
                push(out, "req_bytes", r.req_bytes());
                if let Some(l) = req(out, "req_nums", r.req_nums()) {
                    scalars!(out, "req_nums", l);
                }
                if let Some(l) = req(out, "req_names", r.req_names()) {
                    strs!(out, "req_names", l);
                }
                if let Some(l) = req(out, "req_blobs", r.req_blobs()) {
                    blobs!(out, "req_blobs", l);
                }
                if let Some(l) = req(out, "req_small", r.req_small()) {
                    tables!(out, "req_small", l, small, 0);
                }
                if let Some(l) = req(out, "req_big", r.req_big()) {
                    tables!(out, "req_big", l, big, 0);
                }
                if let Some(t) = req(out, "req_tab", r.req_tab()) {
                    small(t, 0, out);
                }
                if let Some(p) = req(out, "req_pick", r.req_pick()) {
                    pick(p, out);
                }
                push(out, "d_i8", r.d_i8());
                push(out, "d_i64", r.d_i64());
                push(out, "d_f32", r.d_f32().to_bits());
                push(out, "d_f64", r.d_f64().to_bits());
                push(out, "d_bool", r.d_bool());
                push(out, "d_mode", r.d_mode());
                push(out, "pixel", r.pixel());
                push(out, "pair", r.pair().a);
                push(out, "pair.w", r.pair().w.to_bits());
                if let Some(l) = opt(out, "bools", r.bools()) {
                    scalars!(out, "bools", l);
                }
                if let Some(l) = opt(out, "modes", r.modes()) {
                    scalars!(out, "modes", l);
                }
                if let Some(l) = opt(out, "pixels", r.pixels()) {
                    scalars!(out, "pixels", l);
                }
                if let Some(t) = opt(out, "opt_tab", r.opt_tab()) {
                    big(t, 0, out);
                }
                if let Some(p) = opt(out, "opt_pick", r.opt_pick()) {
                    pick(p, out);
                }
                push(out, "last", r.last());
            }

            fn entry(e: $Entry, _d: u32, out: &mut Out) {
                push(out, "account", e.account());
                push(out, "amount", e.amount());
                push(out, "memo", e.memo());
            }

            pub fn transaction(r: &$Tx, out: &mut Out) {
                push(out, "id", r.id());
                push(out, "ts", r.ts());
                push(out, "currency", r.currency());
                push(out, "from_shard", r.from_shard());
                push(out, "to_shard", r.to_shard());
                if let Some(l) = req(out, "entries", r.entries()) {
                    tables!(out, "entries", l, entry, 0);
                }
                push(out, "note", r.note());
            }

            fn entity(e: $Entity, _d: u32, out: &mut Out) {
                push(out, "id", e.id());
                push(out, "pos", e.pos());
                push(out, "vel", e.vel());
                push(out, "hp", e.hp());
                push(out, "alive", e.alive());
            }

            pub fn frame(r: &$Frame, out: &mut Out) {
                push(out, "tick", r.tick());
                if let Some(l) = req(out, "entities", r.entities()) {
                    tables!(out, "entities", l, entity, 0);
                }
            }

            pub fn telemetry(r: &$Tel, out: &mut Out) {
                push(out, "device", r.device());
                push(out, "ts", r.ts());
                push(out, "temp", r.temp().to_bits());
                push(out, "humidity", r.humidity().map(f32::to_bits));
                push(out, "battery", r.battery());
            }

            pub fn chunk(r: &$Chunk, out: &mut Out) {
                push(out, "stream_id", r.stream_id());
                push(out, "seq", r.seq());
                push(out, "data", r.data());
            }
        }
    };
}

walkers! {
    mod checked;
    conformance: g::Root<'_>, g::Leaf<'_>, Choice, g::Extra<'_>, g::Holder<'_>;
    edge: e::Edge<'_>, e::Small<'_>, e::Big<'_>, Pick;
    bank: graven_schemas::bank::Transaction<'_>, graven_schemas::bank::Entry<'_>;
    game: graven_schemas::game::Frame<'_>, graven_schemas::game::Entity<'_>;
    iot: graven_schemas::iot::Telemetry<'_>;
    stream: graven_schemas::stream::Chunk<'_>;
}

walkers! {
    mod verified;
    conformance: g::RootVerified<'_>, g::LeafVerified<'_>, ChoiceVerified, g::ExtraVerified<'_>, g::HolderVerified<'_>;
    edge: e::EdgeVerified<'_>, e::SmallVerified<'_>, e::BigVerified<'_>, PickVerified;
    bank: graven_schemas::bank::TransactionVerified<'_>, graven_schemas::bank::EntryVerified<'_>;
    game: graven_schemas::game::FrameVerified<'_>, graven_schemas::game::EntityVerified<'_>;
    iot: graven_schemas::iot::TelemetryVerified<'_>;
    stream: graven_schemas::stream::ChunkVerified<'_>;
}

/// A root: reads with `read` (checked) and with `verified`, and calls `f` with both walks
/// (`None` when the read failed).
macro_rules! roots {
    ($($T:path => $walk:ident),* $(,)?) => {
        /// `read` of each root + checked walk of every accessor (never panics).
        pub fn read_all(data: &[u8]) {
            $(
                if let Ok(r) = <$T>::read(data) {
                    checked::$walk(&r, &mut Vec::new());
                }
            )*
        }
        /// `verified` of each root + walk of the verified view.
        pub fn verify_all(data: &[u8]) {
            $(
                if let Ok(v) = <$T>::verified(data) {
                    verified::$walk(&v, &mut Vec::new());
                }
            )*
        }
        /// If `verified` accepts: `read` accepts too, and the verified walk equals the
        /// checked walk, accessor by accessor.
        pub fn differential(data: &[u8]) {
            $(
                if let Ok(v) = <$T>::verified(data) {
                    let r = <$T>::read(data).expect(concat!(stringify!($T), ": verified accepts, read refuses"));
                    let (mut a, mut b) = (Vec::new(), Vec::new());
                    verified::$walk(&v, &mut a);
                    // `verified` accepted ⇒ every accessor reads without error (otherwise verify
                    // skipped something the spec says to reject).
                    let errs = errors(&a);
                    assert!(errs.is_empty(), concat!(stringify!($T), ": verified but an accessor fails: {:?}"), errs);
                    checked::$walk(&r, &mut b);
                    assert_eq!(a, b, concat!(stringify!($T), ": verified view ≠ checked reader"));
                    let mut c = Vec::new();
                    checked::$walk(&v.reader(), &mut c);
                    assert_eq!(a, c, concat!(stringify!($T), ": view ≠ reader()"));
                }
            )*
        }
    };
}

roots! {
    graven_conformance::generated::Root => root,
    graven_conformance::generated::Extra => extra,
    graven_conformance::generated::Holder => holder,
    graven_codegen_tests::edge::Edge => edge,
    graven_schemas::bank::Transaction => transaction,
    graven_schemas::game::Frame => frame,
    graven_schemas::iot::Telemetry => telemetry,
    graven_schemas::stream::Chunk => chunk,
}
